import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useLocation, useNavigate } from 'react-router-dom';
import SearchBar from '../components/SearchBar';

export default function SearchResults() {
  const [countries, setCountries] = useState([]);
  const [sortBy, setSortBy] = useState('');
  const location = useLocation();
  const navigate = useNavigate();

  const fetchCountries = async () => {
    const query = new URLSearchParams(location.search);
    if (sortBy) query.set('sortBy', sortBy);
    const { data } = await axios.get(`http://localhost:5000/api/countries/search?${query.toString()}`);
    setCountries(data.results);
  };

  useEffect(() => {
    fetchCountries();
  }, [location.search, sortBy]);

  return (
    <div>
      <SearchBar onSearch={() => {}} compact={true} />
      <select onChange={e => setSortBy(e.target.value)}>
        <option value="">Sort By</option>
        <option value="name">Name</option>
        <option value="capital">Capital</option>
        <option value="currency">Currency</option>
      </select>
      <div className="grid">
        {countries.map(c => (
          <div key={c.cca2} onClick={() => navigate(`/country/${c.cca2}`)}>
            <h3>{c.name}</h3>
            <p>{c.capital}</p>
            <p>{c.currencies.join(', ')}</p>
            <span>{c.flag}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
